1	// The Agent message box (the Composer proposal on the "JusPrin v2" canvas):
2	// one bordered box holding the staged attachments, the text field, and a
3	// toolbar with + on the left and Send on the right. The field starts one
4	// line high and grows a line at a time up to component.composer.maxLines,
5	// then scrolls inside the box; the toolbar stays.
6	//
7	// Input rules from the handoff: Enter sends, Shift+Enter inserts a newline,
8	// and Enter during IME composition accepts the composition without sending.
9	// Normal selection, clipboard, and focus behavior are left to the browser
10	// engine. The in-progress draft is reported (debounced) so the host can keep
11	// it with the project's saved state; reconnecting restores it via initialText.
12	//
13	// Attachments enter through the + menu's file picker, drag-and-drop, or
14	// pasting an image; staged attachments render as removable rows, and a
15	// message may be sent with attachments and no text. The host owns decoding
16	// and storage -- the composer only hands it files.
17	
18	import { ChangeEvent, ClipboardEvent, DragEvent, KeyboardEvent, ReactNode, useEffect, useLayoutEffect, useRef, useState } from 'react';
19	import { AttachmentInfo, AttachmentPickKind, AttachmentSource, ChatModelChoice, ModelCatalogPayload } from '../bridge/protocol';
20	import { composerInputMaxHeight } from '../tokens';
21	import { AttachmentChip } from './AttachmentChip';
22	import { ActionMenu } from './ChatNavigation';
23	import { ModelPickers } from './ModelPickers';
24	
25	// What the + menu offers: the four kinds the design names. In the app each
26	// opens the operating system's file dialog through the host, which filters
27	// it to the extensions it files under that kind. `accept` is the browser
28	// input's copy of the same lists, used only where the page runs without
29	// that host (review pages, tests). Text and SVG files are accepted too, by
30	// dropping them.
31	export const ATTACHMENT_CHOICES: readonly { label: string; kind: AttachmentPickKind; accept: string }[] = [
32	  { label: 'Photo or image', kind: 'image', accept: '.png,.jpg,.jpeg,.gif,.webp' },
33	  { label: '3D model (STL, 3MF, STEP)', kind: 'model',
34	    accept: '.stl,.3mf,.step,.stp,.obj,.amf,.oltp,.drc,.ply,.usd,.usda,.usdc,.usdz,.abc' },
35	  { label: 'G-code', kind: 'gcode', accept: '.gcode,.g,.gco' },
36	  { label: 'Document (PDF)', kind: 'pdf', accept: '.pdf' },
37	];
38	
39	interface Props {
40	  disabled: boolean;
41	  disabledReason?: string;
42	  streaming: boolean;
43	  initialText?: string;
44	  attachments: AttachmentInfo[]; // staged attachments only
45	  onSend: (text: string) => void;
46	  onStop: () => void;
47	  onAttachFiles: (files: File[], source: AttachmentSource) => void;
48	  // Opens the host's own file dialog for one kind; absent where the host
49	  // cannot, and the browser's file input is used instead.
50	  onPickFiles?: (kind: AttachmentPickKind) => void;
51	  onRemoveAttachment: (id: string) => void;
52	  onDraftChange?: (text: string) => void;
53	  draftDebounceMs?: number;
54	  // Fired on the keystroke itself, not on the debounced draft save. Anything
55	  // covering the thread uses this to get out of the way immediately.
56	  onTyping?: () => void;
57	  // A likely answer to what was just asked, rather than the standing
58	  // invitation. The printer panel writes one per turn.
59	  placeholder?: string;
60	  // Labelled "Photo" instead of the + menu: in the printer panel a picture
61	  // is a primary way to say which printer this is, not an extra.
62	  photoButton?: boolean;
63	  // What the band says above the field when the field cannot be used as it
64	  // is: the notice on an earlier chat, or a recovery alert.
65	  notice?: ReactNode;
66	  // False where nothing can be attached at all, so the action is left out
67	  // rather than shown disabled: a read-only shell has only its field and Send.
68	  attachable?: boolean;
69	  // The chat's model and thinking pickers, where the host offers them.
70	  models?: ModelCatalogPayload;
71	  chatModel?: ChatModelChoice;
72	  onChooseModel?: (choice: ChatModelChoice) => void;
73	}
74	
75	export function Composer({
76	  disabled,
77	  disabledReason,
78	  streaming,
79	  initialText,
80	  attachments,
81	  onSend,
82	  onStop,
83	  onAttachFiles,
84	  onPickFiles,
85	  onRemoveAttachment,
86	  onDraftChange,
87	  draftDebounceMs = 300,
88	  onTyping,
89	  placeholder,
90	  photoButton,
91	  notice,
92	  attachable = true,
93	  models,
94	  chatModel,
95	  onChooseModel,
96	}: Props) {
97	  const [text, setText] = useState(initialText ?? '');
98	  const [dragging, setDragging] = useState(false);
99	  const draftTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
100	  const pendingDraft = useRef(false);
101	  const latestText = useRef(initialText ?? '');
102	  const fileInput = useRef<HTMLInputElement>(null);
103	  const field = useRef<HTMLTextAreaElement>(null);
104	  const choices = useRef<HTMLDivElement>(null);
105	  const [narrow, setNarrow] = useState(false);
106	
107	  // Grow the field to its text, up to the line limit; past it the field
108	  // scrolls. A field that is not laid out (inside a hidden view) measures 0
109	  // and keeps its height until its text next changes.
110	  useLayoutEffect(() => {
111	    const element = field.current;
112	    if (!element) return;
113	    const previous = element.style.height;
114	    element.style.height = 'auto';
115	    const content = element.scrollHeight;
116	    element.style.height = content > 0 ? `${Math.min(content, composerInputMaxHeight())}px` : previous;
117	  }, [text]);
118	
119	  // A narrow pane: when the choices at full length do not fit beside Send,
120	  // the thinking picker drops "Thinking:", and the model picker's name is
121	  // cut if it still does not fit. Measured with the labels in full (the
122	  // measuring class undoes the narrow one and the shrinking) so the answer
123	  // follows the labels' real lengths, not a fixed breakpoint.
124	  useLayoutEffect(() => {
125	    const element = choices.current;
126	    if (!element) return;
127	    const measure = () => {
128	      element.classList.add('composer-choices--measuring');
129	      const needed = element.scrollWidth;
130	      element.classList.remove('composer-choices--measuring');
131	      setNarrow(needed > element.clientWidth);
132	    };
133	    measure();
134	    const observer = new ResizeObserver(measure);
135	    observer.observe(element);
136	    return () => observer.disconnect();
137	  }, [models, chatModel]);
138	
139	  // A recovered draft arrives after the first connect; apply it only while
140	  // the composer is untouched so it never clobbers active typing.
141	  const touched = useRef(false);
142	  useEffect(() => {
143	    if (!touched.current && initialText) { setText(initialText); latestText.current = initialText; }
144	    // eslint-disable-next-line react-hooks/exhaustive-deps
145	  }, [initialText]);
146	
147	  useEffect(() => {
148	    return () => {
149	      if (draftTimer.current !== null) clearTimeout(draftTimer.current);
150	      if (pendingDraft.current) onDraftChange?.(latestText.current);
151	    };
152	  }, []);
153	
154	  const reportDraft = (value: string) => {
155	    if (!onDraftChange) return;
156	    if (draftTimer.current !== null) clearTimeout(draftTimer.current);
157	    pendingDraft.current = true;
158	    latestText.current = value;
159	    draftTimer.current = setTimeout(() => { pendingDraft.current = false; onDraftChange(value); }, draftDebounceMs);
160	  };
161	
162	  const hasSendable = attachments.some((a) => a.state === 'staged');
163	  const canSend = (!!text.trim() || hasSendable) && !disabled && !streaming;
164	
165	  const send = () => {
166	    if (!canSend) return;
167	    if (draftTimer.current !== null) clearTimeout(draftTimer.current);
168	    pendingDraft.current = false;
169	    onSend(text.trim());
170	    setText('');
171	  };
172	
173	  const handleKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
174	    if (event.key !== 'Enter' || event.shiftKey) return;
175	    // 229 is the legacy IME-processing keyCode some engines still report.
176	    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
177	    event.preventDefault();
178	    send();
179	  };
180	
181	  // The host's dialog when there is one: a web view's file input shows every
182	  // file on macOS whatever `accept` says.
183	  const pickFiles = (choice: (typeof ATTACHMENT_CHOICES)[number]) => {
184	    if (onPickFiles) {
185	      onPickFiles(choice.kind);
186	      return;
187	    }
188	    if (!fileInput.current) return;
189	    fileInput.current.accept = choice.accept;
190	    fileInput.current.click();
191	  };
192	
193	  const handleFiles = (files: FileList | null, source: AttachmentSource) => {
194	    if (!files || files.length === 0) return;
195	    onAttachFiles(Array.from(files), source);
196	  };
197	
198	  const handlePickerChange = (event: ChangeEvent<HTMLInputElement>) => {
199	    handleFiles(event.target.files, 'picker');
200	    event.target.value = ''; // allow re-picking the same file
201	  };
202	
203	  const handlePaste = (event: ClipboardEvent<HTMLTextAreaElement>) => {
204	    const files = Array.from(event.clipboardData.files ?? []);
205	    if (files.length > 0) {
206	      event.preventDefault();
207	      onAttachFiles(files, 'clipboard');
208	    }
209	  };
210	
211	  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
212	    event.preventDefault();
213	    setDragging(false);
214	    if (disabled) return;
215	    handleFiles(event.dataTransfer.files, 'drop');
216	  };
217	
218	  return (
219	    <div
220	      className={`composer${dragging ? ' dragging' : ''}`}
221	      onDragOver={(event) => {
222	        event.preventDefault();
223	        if (!disabled) setDragging(true);
224	      }}
225	      onDragLeave={() => setDragging(false)}
226	      onDrop={handleDrop}
227	    >
228	      {notice}
229	      <div className="composer-box">
230	        {attachments.length > 0 && (
231	          <div className="composer-attachments" aria-label="Staged attachments">
232	            {attachments.map((attachment) => (
233	              <AttachmentChip key={attachment.id} attachment={attachment} onRemove={onRemoveAttachment} />
234	            ))}
235	          </div>
236	        )}
237	        <textarea
238	          ref={field}
239	          aria-label="Message the Agent"
240	          placeholder={
241	            disabled
242	              ? disabledReason ?? 'The Agent is not available'
243	              : streaming
244	                ? 'Agent is responding…'
245	                // A staged photo waits for the person; it never sends itself.
246	                : photoButton && hasSendable
247	                  ? 'add a note, or just send'
248	                  : placeholder ?? 'Ask about this print or request a change…'
249	          }
250	          value={text}
251	          disabled={disabled}
252	          onChange={(event) => {
253	            touched.current = true;
254	            onTyping?.();
255	            setText(event.target.value);
256	            latestText.current = event.target.value;
257	            reportDraft(event.target.value);
258	          }}
259	          onKeyDown={handleKeyDown}
260	          onPaste={handlePaste}
261	          rows={1}
262	        />
263	        <div className="composer-toolbar">
264	          <div ref={choices} className={narrow ? 'composer-choices composer-choices--narrow' : 'composer-choices'}>
265	            {attachable && (photoButton ? (
266	              <button
267	                type="button"
268	                className="attach-button attach-button-photo"
269	                aria-label="Add a photo"
270	                disabled={disabled}
271	                onClick={() => pickFiles(ATTACHMENT_CHOICES[0])}
272	              >
273	                Photo
274	              </button>
275	            ) : (
276	              // Disabled while the Agent responds, like every choice in the
277	              // toolbar; the field stays open for the next message.
278	              <ActionMenu label="Attach a file" icon="plus" above disabled={disabled || streaming}
279	                items={ATTACHMENT_CHOICES.map((choice) => ({ label: choice.label, onSelect: () => pickFiles(choice) }))} />
280	            ))}
281	            {!photoButton && models && chatModel && onChooseModel && (
282	              <ModelPickers catalog={models} choice={chatModel} disabled={disabled || streaming}
283	                onChoose={onChooseModel} />
284	            )}
285	          </div>
286	          {streaming ? (
287	            <button type="button" className="composer-send composer-stop" onClick={onStop} aria-label="Stop generating">
288	              Stop
289	            </button>
290	          ) : (
291	            <button
292	              type="button"
293	              className="composer-send"
294	              onClick={send}
295	              disabled={!canSend}
296	              aria-label="Send message"
297	            >
298	              Send
299	            </button>
300	          )}
301	        </div>
302	      </div>
303	      <input
304	        ref={fileInput}
305	        type="file"
306	        multiple
307	        className="attach-input"
308	        aria-hidden="true"
309	        tabIndex={-1}
310	        style={{ display: 'none' }}
311	        onChange={handlePickerChange}
312	      />
313	    </div>
314	  );
315	}
316

